-- Native versioned plans and HR attendance reports. Applied208 sources remain immutable.
INSERT INTO sys_perm_resource(resource_code,label)VALUES('attendance_self','本人排班考勤与打卡')ON CONFLICT DO NOTHING;
INSERT INTO sys_role_resource(role_id,resource_code,can_read,can_write)
SELECT id,'attendance_self',true,true FROM sys_role WHERE code IN('store_staff','store_mgr','ty_group_hr_director','ty_company_hr_director','ty_demo_hr_staff','ty_demo_payroll','ty_demo_trainer','ty_demo_recruiter','ty_demo_hr_manager')ON CONFLICT DO NOTHING;

CREATE TABLE ty_time_plan_version(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,group_id bigint NOT NULL REFERENCES ty_group(id),company_id bigint REFERENCES ty_company(id),
 period date NOT NULL CHECK(extract(day FROM period)=1),label text NOT NULL,status text NOT NULL DEFAULT'draft'CHECK(status IN('draft','published','superseded','cancelled')),
 revision integer NOT NULL DEFAULT 1 CHECK(revision>0),source_plan_id bigint REFERENCES ty_time_plan_version(id),source_period_id bigint REFERENCES ty_roster_period(id),
 created_by bigint NOT NULL REFERENCES sys_account(id),published_by bigint REFERENCES sys_account(id),created_at timestamptz NOT NULL DEFAULT now(),published_at timestamptz,source_hash text,
 CHECK(NOT(source_plan_id IS NOT NULL AND source_period_id IS NOT NULL))
);
CREATE TABLE ty_time_change_request(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,plan_id bigint NOT NULL REFERENCES ty_time_plan_version(id),group_id bigint NOT NULL REFERENCES ty_group(id),company_id bigint REFERENCES ty_company(id),
 kind text NOT NULL CHECK(kind IN('shift_swap','secondment','cross_brand_support','store_transfer')),
 status text NOT NULL CHECK(status IN('awaiting_counterparty','pending','approved','rejected','cancelled')),application_state text NOT NULL DEFAULT'pending'CHECK(application_state IN('pending','applied','applied_to_draft','not_applied')),
 plan_revision integer NOT NULL,patches jsonb NOT NULL CHECK(jsonb_typeof(patches)='array'AND jsonb_array_length(patches)>0),before_data jsonb NOT NULL,
 participant_person_ids jsonb NOT NULL CHECK(jsonb_typeof(participant_person_ids)='array'),reason text NOT NULL CHECK(length(btrim(reason))>=4),revision integer NOT NULL DEFAULT 1,
 created_by bigint NOT NULL REFERENCES sys_account(id),decided_by bigint REFERENCES sys_account(id),decision_reason text,created_at timestamptz NOT NULL DEFAULT now(),decided_at timestamptz
);
CREATE TABLE ty_time_plan_day(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,plan_id bigint NOT NULL REFERENCES ty_time_plan_version(id),person_id bigint NOT NULL REFERENCES ty_person(id),employment_id bigint NOT NULL REFERENCES ty_employment(id),home_company_id bigint NOT NULL REFERENCES ty_company(id),work_date date NOT NULL,
 day_kind text NOT NULL DEFAULT'unscheduled'CHECK(day_kind IN('work','rest','unscheduled','annual_leave','sick_leave','personal_leave','holiday','absence')),calendar_note text NOT NULL DEFAULT'',source_ref text,revision integer NOT NULL DEFAULT 1,UNIQUE(plan_id,employment_id,work_date)
);
ALTER TABLE ty_time_change_request ADD COLUMN result_plan_id bigint REFERENCES ty_time_plan_version(id);
CREATE TABLE ty_time_change_consent(
 request_id bigint NOT NULL REFERENCES ty_time_change_request(id),person_id bigint NOT NULL REFERENCES ty_person(id),state text NOT NULL DEFAULT'pending'CHECK(state IN('pending','accepted','rejected')),
 account_id bigint REFERENCES sys_account(id),reason text,acted_at timestamptz,PRIMARY KEY(request_id,person_id)
);
CREATE TABLE ty_time_plan_segment(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,plan_id bigint NOT NULL REFERENCES ty_time_plan_version(id),person_id bigint NOT NULL REFERENCES ty_person(id),employment_id bigint NOT NULL REFERENCES ty_employment(id),
 home_company_id bigint NOT NULL REFERENCES ty_company(id),work_company_id bigint NOT NULL REFERENCES ty_company(id),department_id bigint NOT NULL REFERENCES ty_department(id),work_area_id bigint REFERENCES ty_work_area(id),
 work_date date NOT NULL,start_at timestamptz NOT NULL,end_at timestamptz NOT NULL,shift_code text NOT NULL DEFAULT'TEMP',label text NOT NULL,color text NOT NULL CHECK(color~'^#[0-9A-Fa-f]{6}$'),
 breaks jsonb NOT NULL DEFAULT'[]'CHECK(jsonb_typeof(breaks)='array'),planned_minutes integer NOT NULL CHECK(planned_minutes>0),overtime boolean NOT NULL DEFAULT false,leave_kind text,
 state text NOT NULL DEFAULT'active'CHECK(state IN('active','cancelled')),revision integer NOT NULL DEFAULT 1 CHECK(revision>0),source_ref text,source_segment_id bigint REFERENCES ty_time_plan_segment(id),replaces_segment_id bigint REFERENCES ty_time_plan_segment(id),basis_change_id bigint REFERENCES ty_time_change_request(id),secondment_id bigint,
 created_by bigint NOT NULL REFERENCES sys_account(id),updated_by bigint NOT NULL REFERENCES sys_account(id),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),
 CHECK(end_at>start_at AND end_at<=start_at+interval'48 hours'),CHECK(extract(second FROM start_at)=0 AND extract(second FROM end_at)=0),CHECK(NOT(overtime AND leave_kind IS NOT NULL))
);
CREATE INDEX ty_time_segment_person_interval ON ty_time_plan_segment(person_id,start_at,end_at)WHERE state='active';
CREATE TABLE ty_time_shift_version(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,group_id bigint NOT NULL REFERENCES ty_group(id),code text NOT NULL,name text NOT NULL,color text NOT NULL CHECK(color~'^#[0-9A-Fa-f]{6}$'),
 version integer NOT NULL CHECK(version>0),revision integer NOT NULL DEFAULT 1,segments jsonb NOT NULL CHECK(jsonb_typeof(segments)='array'),created_by bigint NOT NULL REFERENCES sys_account(id),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(group_id,code,version)
);
CREATE TABLE ty_time_report_version(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,group_id bigint NOT NULL REFERENCES ty_group(id),company_id bigint REFERENCES ty_company(id),period date NOT NULL CHECK(extract(day FROM period)=1),
 label text NOT NULL,status text NOT NULL DEFAULT'draft'CHECK(status IN('draft','confirmed')),revision integer NOT NULL DEFAULT 1 CHECK(revision>0),grain text NOT NULL CHECK(grain IN('daily','monthly')),
 source_plan_id bigint REFERENCES ty_time_plan_version(id),source_period_id bigint REFERENCES ty_roster_period(id),source_report_id bigint REFERENCES ty_time_report_version(id),source_hash text,
 created_by bigint NOT NULL REFERENCES sys_account(id),confirmed_by bigint REFERENCES sys_account(id),created_at timestamptz NOT NULL DEFAULT now(),confirmed_at timestamptz,
 CHECK(num_nonnulls(source_plan_id,source_period_id,source_report_id)<=1)
);
-- A report header is a historical collection, not the replacement boundary.
-- Every employer/receiving employee-month has one current fact root across daily/monthly grain.
CREATE TABLE ty_time_report_root(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 group_id bigint NOT NULL REFERENCES ty_group(id),employment_id bigint NOT NULL REFERENCES ty_employment(id),person_id bigint NOT NULL REFERENCES ty_person(id),
 period date NOT NULL CHECK(extract(day FROM period)=1),perspective text NOT NULL CHECK(perspective IN('employer','receiving')),owner_company_id bigint NOT NULL REFERENCES ty_company(id),
 current_report_id bigint REFERENCES ty_time_report_version(id),head_revision integer NOT NULL DEFAULT 0 CHECK(head_revision>=0),
 UNIQUE(group_id,employment_id,period,perspective,owner_company_id),CHECK((current_report_id IS NULL)=(head_revision=0))
);
CREATE TABLE ty_time_report_scope(
 report_id bigint NOT NULL REFERENCES ty_time_report_version(id),root_id bigint NOT NULL REFERENCES ty_time_report_root(id),
 expected_head_revision integer NOT NULL CHECK(expected_head_revision>=0),expected_current_report_id bigint REFERENCES ty_time_report_version(id),
 PRIMARY KEY(report_id,root_id),CHECK((expected_current_report_id IS NULL)=(expected_head_revision=0))
);
CREATE TABLE ty_time_report_line(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,report_id bigint NOT NULL REFERENCES ty_time_report_version(id),line_key text NOT NULL,person_id bigint NOT NULL REFERENCES ty_person(id),employment_id bigint NOT NULL REFERENCES ty_employment(id),
 home_company_id bigint NOT NULL REFERENCES ty_company(id),scope_company_id bigint NOT NULL REFERENCES ty_company(id),receiving_store_only boolean NOT NULL DEFAULT false,work_date date,day_kind text,
 planned_minutes integer CHECK(planned_minutes>=0),actual_minutes integer CHECK(actual_minutes>=0),worked_minutes integer CHECK(worked_minutes>=0),overtime_minutes integer CHECK(overtime_minutes>=0),
 paid_leave_minutes integer CHECK(paid_leave_minutes>=0),unpaid_leave_minutes integer CHECK(unpaid_leave_minutes>=0),late_minutes integer CHECK(late_minutes>=0),early_minutes integer CHECK(early_minutes>=0),missing_punches integer CHECK(missing_punches>=0),
 overtime_day_type text NOT NULL DEFAULT'unknown'CHECK(overtime_day_type IN('workday','restday','statutory_holiday','unknown')),
 original_values jsonb NOT NULL,source_segment_ids jsonb NOT NULL DEFAULT'[]'CHECK(jsonb_typeof(source_segment_ids)='array'),revision integer NOT NULL DEFAULT 1 CHECK(revision>0),UNIQUE(report_id,line_key)
);
CREATE UNIQUE INDEX ty_time_daily_root_day ON ty_time_report_line(report_id,employment_id,scope_company_id,receiving_store_only,work_date)WHERE work_date IS NOT NULL;
CREATE UNIQUE INDEX ty_time_monthly_root ON ty_time_report_line(report_id,employment_id,scope_company_id,receiving_store_only)WHERE work_date IS NULL;
ALTER TABLE ty_time_report_line ADD COLUMN calendar_days integer,ADD COLUMN work_days integer,ADD COLUMN rest_days integer,ADD COLUMN leave_days integer;
CREATE TABLE ty_time_report_adjustment(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,report_id bigint NOT NULL REFERENCES ty_time_report_version(id),line_id bigint NOT NULL REFERENCES ty_time_report_line(id),
 before_values jsonb NOT NULL,after_values jsonb NOT NULL,reason text NOT NULL CHECK(length(btrim(reason))>=4),evidence_ref text NOT NULL,actor_id bigint NOT NULL REFERENCES sys_account(id),created_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE ty_time_raw_punch(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,group_id bigint NOT NULL REFERENCES ty_group(id),company_id bigint NOT NULL REFERENCES ty_company(id),person_id bigint NOT NULL REFERENCES ty_person(id),employment_id bigint NOT NULL REFERENCES ty_employment(id),
 segment_ref text,direction text NOT NULL CHECK(direction IN('in','out')),punched_at timestamptz NOT NULL,source_key text NOT NULL,evidence_ref text,source text NOT NULL DEFAULT'self'CHECK(source='self'),actor_id bigint NOT NULL REFERENCES sys_account(id),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(group_id,person_id,source_key)
);
CREATE TABLE ty_time_punch_correction_request(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,group_id bigint NOT NULL REFERENCES ty_group(id),company_id bigint NOT NULL REFERENCES ty_company(id),person_id bigint NOT NULL REFERENCES ty_person(id),employment_id bigint NOT NULL REFERENCES ty_employment(id),
 segment_ref text NOT NULL,direction text NOT NULL CHECK(direction IN('in','out')),corrected_at timestamptz NOT NULL,reason text NOT NULL CHECK(length(btrim(reason))>=4),evidence_ref text NOT NULL,
 status text NOT NULL DEFAULT'pending'CHECK(status IN('pending','approved','rejected')),revision integer NOT NULL DEFAULT 1,created_by bigint NOT NULL REFERENCES sys_account(id),decided_by bigint REFERENCES sys_account(id),decision_reason text,result_report_id bigint REFERENCES ty_time_report_version(id),created_at timestamptz NOT NULL DEFAULT now(),decided_at timestamptz
);
ALTER TABLE ty_time_punch_correction_request ADD COLUMN period date NOT NULL;
ALTER TABLE ty_time_report_line ADD COLUMN source_correction_id bigint REFERENCES ty_time_punch_correction_request(id);
CREATE TABLE ty_time_import_batch(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,group_id bigint NOT NULL REFERENCES ty_group(id),company_id bigint REFERENCES ty_company(id),period date NOT NULL,
 kind text NOT NULL CHECK(kind IN('plan','attendance_daily','attendance_monthly')),namespace text NOT NULL,filename text NOT NULL,source_hash text NOT NULL,parsed_rows jsonb NOT NULL,issues jsonb NOT NULL,
 head_snapshot jsonb NOT NULL DEFAULT'[]'CHECK(jsonb_typeof(head_snapshot)='array'),status text NOT NULL CHECK(status IN('validated','invalid','applied')),revision integer NOT NULL DEFAULT 1,created_by bigint NOT NULL REFERENCES sys_account(id),result_plan_id bigint REFERENCES ty_time_plan_version(id),result_report_id bigint REFERENCES ty_time_report_version(id),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(group_id,period,namespace,kind,source_hash)
);

CREATE FUNCTION fn_ty_time216_keep()RETURNS trigger LANGUAGE plpgsql SET search_path='' AS $$BEGIN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='时间来源、版本与办理历史不能直接删除或改写';END;$$;
CREATE FUNCTION fn_ty_time216_version_guard()RETURNS trigger LANGUAGE plpgsql SET search_path='' AS $$
BEGIN
 IF TG_OP='UPDATE' THEN
  IF NEW.group_id<>OLD.group_id OR NEW.company_id IS DISTINCT FROM OLD.company_id OR NEW.period<>OLD.period OR NEW.created_by<>OLD.created_by THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='版本身份、范围与原建立人不可改写';END IF;
  IF TG_TABLE_NAME='ty_time_report_version'AND OLD.status='confirmed' THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='已核准考勤版本不可改写';END IF;
  IF TG_TABLE_NAME='ty_time_plan_version'AND OLD.status<>'draft'AND(to_jsonb(NEW)-ARRAY['status','revision'])IS DISTINCT FROM(to_jsonb(OLD)-ARRAY['status','revision'])THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='已发布排班的事实快照不可改写';END IF;
  IF TG_TABLE_NAME='ty_time_plan_version'AND NOT((OLD.status='draft'AND NEW.status IN('draft','published','cancelled'))OR(OLD.status='published'AND NEW.status='superseded'))THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='排班版本状态不能重新打开或退回草稿';END IF;
  IF TG_TABLE_NAME='ty_time_report_version'AND NEW.status NOT IN('draft','confirmed')THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='核勤状态变化无效';END IF;
  IF NEW.revision<>OLD.revision+1 THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='版本修订号须连续递增';END IF;
 END IF;
 IF NEW.company_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.ty_company WHERE id=NEW.company_id AND group_id=NEW.group_id)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='版本公司须属于本集团';END IF;
 IF NEW.source_period_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.ty_roster_period s WHERE s.id=NEW.source_period_id AND s.group_id=NEW.group_id AND s.period=NEW.period)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='基线来源须为同集团同月';END IF;
 IF NEW.source_plan_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.ty_time_plan_version s WHERE s.id=NEW.source_plan_id AND s.group_id=NEW.group_id AND s.period=NEW.period AND(TG_TABLE_NAME<>'ty_time_plan_version'OR s.id<>NEW.id))THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='排班来源须为同集团同月且不得自引用';END IF;
 IF TG_TABLE_NAME='ty_time_report_version' THEN IF NEW.source_report_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.ty_time_report_version s WHERE s.id=NEW.source_report_id AND s.id<NEW.id AND s.group_id=NEW.group_id AND s.period=NEW.period AND s.grain=NEW.grain)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='核勤替代链须保持集团月份范围和粒度一致且不能循环';END IF;END IF;
 IF TG_TABLE_NAME='ty_time_report_version' THEN IF NEW.status='confirmed'AND(NEW.source_hash IS NULL OR length(NEW.source_hash)<>64 OR NEW.confirmed_by IS NULL OR NEW.confirmed_at IS NULL OR NOT EXISTS(SELECT 1 FROM public.ty_time_report_line WHERE report_id=NEW.id))THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='核准须有完整来源哈希、复核人及事实行';END IF;END IF;
 IF TG_TABLE_NAME='ty_time_plan_version' THEN IF NEW.status='published'AND(NEW.published_by IS NULL OR NEW.published_at IS NULL OR NEW.source_hash IS NULL)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='发布须有复核人与冻结快照';END IF;END IF;
 RETURN NEW;
END;$$;
CREATE TRIGGER ty_time_plan_version_guard BEFORE INSERT OR UPDATE ON ty_time_plan_version FOR EACH ROW EXECUTE FUNCTION fn_ty_time216_version_guard();
CREATE TRIGGER ty_time_report_version_guard BEFORE INSERT OR UPDATE ON ty_time_report_version FOR EACH ROW EXECUTE FUNCTION fn_ty_time216_version_guard();
CREATE FUNCTION fn_ty_time216_day_guard()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$
DECLARE p public.ty_time_plan_version%ROWTYPE;e public.ty_employment%ROWTYPE;
BEGIN
 SELECT*INTO p FROM public.ty_time_plan_version WHERE id=NEW.plan_id FOR UPDATE;SELECT*INTO e FROM public.ty_employment WHERE id=NEW.employment_id;
 IF p.status<>'draft'OR e.group_id<>p.group_id OR e.person_id<>NEW.person_id OR e.company_id<>NEW.home_company_id OR date_trunc('month',NEW.work_date)::date<>p.period OR NEW.work_date<e.hire_date OR(e.leave_date IS NOT NULL AND NEW.work_date>e.leave_date)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='排班日须属于有效关系及可编辑计划';END IF;
 IF TG_OP='UPDATE'AND(NEW.plan_id<>OLD.plan_id OR NEW.employment_id<>OLD.employment_id OR NEW.person_id<>OLD.person_id OR NEW.work_date<>OLD.work_date OR NEW.home_company_id<>OLD.home_company_id)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='排班日身份不可改写';END IF;RETURN NEW;
END;$$;
CREATE TRIGGER ty_time_plan_day_guard BEFORE INSERT OR UPDATE ON ty_time_plan_day FOR EACH ROW EXECUTE FUNCTION fn_ty_time216_day_guard();
CREATE FUNCTION fn_ty_time216_segment_guard()RETURNS trigger LANGUAGE plpgsql SET search_path='' AS $$
DECLARE p public.ty_time_plan_version%ROWTYPE;e public.ty_employment%ROWTYPE;r jsonb;bstart timestamptz;bend timestamptz;break_mins integer:=0;prior_end timestamptz;secondment_ok boolean:=false;
BEGIN
 SELECT*INTO p FROM public.ty_time_plan_version WHERE id=NEW.plan_id FOR UPDATE;SELECT*INTO e FROM public.ty_employment WHERE id=NEW.employment_id;
 IF p.status<>'draft' OR e.person_id<>NEW.person_id OR e.company_id<>NEW.home_company_id OR e.group_id<>p.group_id OR e.status='cancelled'OR NEW.work_date<e.hire_date OR(e.leave_date IS NOT NULL AND NEW.end_at>(e.leave_date+1)::timestamp AT TIME ZONE'Asia/Shanghai')OR date_trunc('month',NEW.work_date)::date<>p.period OR (NEW.start_at AT TIME ZONE'Asia/Shanghai')::date<>NEW.work_date THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='排班版本、有效雇佣、工作日和完整时间须一致';END IF;
 IF TG_OP='UPDATE'AND(NEW.plan_id<>OLD.plan_id OR NEW.person_id<>OLD.person_id OR NEW.employment_id<>OLD.employment_id OR NEW.work_date<>OLD.work_date OR NEW.home_company_id<>OLD.home_company_id)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='跨人跨日移动须原子替代并留血缘';END IF;
 IF NOT EXISTS(SELECT 1 FROM public.ty_company WHERE id=NEW.work_company_id AND group_id=p.group_id)OR NOT EXISTS(SELECT 1 FROM public.ty_department WHERE id=NEW.department_id AND company_id=NEW.work_company_id)OR(NEW.work_area_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.ty_work_area WHERE id=NEW.work_area_id AND company_id=NEW.work_company_id AND department_id=NEW.department_id))THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='排班工作门店、部门、档口归属不一致';END IF;
 IF NEW.secondment_id IS NOT NULL THEN
  IF to_regclass('public.ty_hr_secondment')IS NULL THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='借调来源尚未安装，不得猜测生效';END IF;
  EXECUTE 'SELECT EXISTS(SELECT 1 FROM public.ty_hr_secondment x WHERE x.id=$1 AND x.group_id=$2 AND x.person_id=$3 AND x.employment_id=$4 AND x.company_id=$5 AND x.receiving_company_id=$6 AND x.department_id=$7 AND x.work_area_id IS NOT DISTINCT FROM $8 AND x.valid_from<=($9 AT TIME ZONE ''Asia/Shanghai'')::date AND x.valid_to>=($10 AT TIME ZONE ''Asia/Shanghai'')::date+CASE WHEN ($10 AT TIME ZONE ''Asia/Shanghai'')::time=''00:00''THEN 0 ELSE 1 END AND x.approved_by IS NOT NULL)' INTO secondment_ok USING NEW.secondment_id,p.group_id,NEW.person_id,NEW.employment_id,NEW.home_company_id,NEW.work_company_id,NEW.department_id,NEW.work_area_id,NEW.start_at,NEW.end_at;
  IF NOT secondment_ok THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='借调依据须匹配实际关系、接收组织、档口及完整班段有效区间';END IF;
 END IF;
 IF NEW.state='active'AND NEW.work_company_id<>NEW.home_company_id AND NOT(secondment_ok OR
  EXISTS(SELECT 1 FROM public.ty_time_change_request c CROSS JOIN LATERAL jsonb_array_elements(c.patches)x WHERE c.id=NEW.basis_change_id AND c.group_id=p.group_id AND c.status='approved'AND(x->>'employment_id')::bigint=NEW.employment_id AND(x->>'work_company_id')::bigint=NEW.work_company_id AND(x->>'department_id')::bigint=NEW.department_id AND(x->>'start_at')::timestamptz=NEW.start_at AND(x->>'end_at')::timestamptz=NEW.end_at)
  OR EXISTS(SELECT 1 FROM public.ty_time_plan_segment x WHERE x.id=NEW.source_segment_id AND x.state='active'AND x.person_id=NEW.person_id AND x.employment_id=NEW.employment_id AND x.work_date=NEW.work_date AND x.work_company_id=NEW.work_company_id AND x.start_at=NEW.start_at AND x.end_at=NEW.end_at)
  OR EXISTS(SELECT 1 FROM public.ty_roster_segment x JOIN public.ty_roster_day d ON d.id=x.day_id JOIN public.ty_roster_period b ON b.id=d.period_id WHERE NEW.source_ref='base:'||x.id AND b.group_id=p.group_id AND d.person_id=NEW.person_id AND d.employment_id=NEW.employment_id AND d.work_date=NEW.work_date AND x.work_company_id=NEW.work_company_id AND x.start_at AT TIME ZONE'Asia/Shanghai'=NEW.start_at AND x.end_at AT TIME ZONE'Asia/Shanghai'=NEW.end_at AND EXISTS(SELECT 1 FROM public.ty_roster_change c CROSS JOIN LATERAL jsonb_array_elements(c.patches)z WHERE c.period_id=b.id AND c.status='approved'AND(z->>'segment_id')::bigint=x.id AND(z->>'work_company_id')::bigint=x.work_company_id))
 )THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='跨店保留原雇佣须有已批准工作依据，不得由通讯录或复制伪造入职借调';END IF;
 FOR r IN SELECT value FROM jsonb_array_elements(NEW.breaks)ORDER BY(value->>'start_at')::timestamptz LOOP
  bstart:=(r->>'start_at')::timestamptz;bend:=(r->>'end_at')::timestamptz;
  IF bstart IS NULL OR bend IS NULL OR bend<=bstart OR bstart<NEW.start_at OR bend>NEW.end_at OR coalesce((r->>'paid')::boolean,true)OR(prior_end IS NOT NULL AND bstart<prior_end)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='不计薪休息须为班段内不重叠的明确区间';END IF;
  break_mins:=break_mins+(extract(epoch FROM(bend-bstart))/60)::integer;prior_end:=bend;
 END LOOP;
 NEW.planned_minutes:=(extract(epoch FROM(NEW.end_at-NEW.start_at))/60)::integer-break_mins;
 IF NEW.state='active' THEN
  PERFORM pg_advisory_xact_lock(hashtextextended('tyhr-time216:'||p.group_id||':'||NEW.person_id,0));
  IF EXISTS(SELECT 1 FROM public.ty_time_plan_segment x WHERE x.plan_id=NEW.plan_id AND x.person_id=NEW.person_id AND x.state='active'AND x.id<>NEW.id AND x.start_at<NEW.end_at AND NEW.start_at<x.end_at)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='同永久人员跨雇佣跨门店班段不得重叠';END IF;
 END IF;RETURN NEW;
END;$$;
CREATE TRIGGER ty_time_plan_segment_guard BEFORE INSERT OR UPDATE ON ty_time_plan_segment FOR EACH ROW EXECUTE FUNCTION fn_ty_time216_segment_guard();
CREATE FUNCTION fn_ty_time216_report_line_guard()RETURNS trigger LANGUAGE plpgsql SET search_path='' AS $$
DECLARE r public.ty_time_report_version%ROWTYPE;e public.ty_employment%ROWTYPE;
BEGIN
 SELECT*INTO r FROM public.ty_time_report_version WHERE id=NEW.report_id FOR UPDATE;SELECT*INTO e FROM public.ty_employment WHERE id=NEW.employment_id;
 IF r.status<>'draft'OR e.group_id<>r.group_id OR e.person_id<>NEW.person_id OR e.company_id<>NEW.home_company_id OR NOT EXISTS(SELECT 1 FROM public.ty_company WHERE id=NEW.scope_company_id AND group_id=r.group_id)OR(NOT NEW.receiving_store_only AND NEW.scope_company_id<>NEW.home_company_id)OR(r.grain='monthly'AND NEW.work_date IS NOT NULL)OR(r.grain='daily'AND(NEW.work_date IS NULL OR date_trunc('month',NEW.work_date)::date<>r.period))THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='考勤行须对应版本粒度、人员实际关系及雇主或借入店口径';END IF;
 IF TG_OP='UPDATE'AND(NEW.report_id<>OLD.report_id OR NEW.line_key<>OLD.line_key OR NEW.person_id<>OLD.person_id OR NEW.employment_id<>OLD.employment_id OR NEW.original_values IS DISTINCT FROM OLD.original_values OR NEW.source_segment_ids IS DISTINCT FROM OLD.source_segment_ids)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='核定不能改写原始行身份与来源快照';END IF;RETURN NEW;
END;$$;
CREATE TRIGGER ty_time_report_line_guard BEFORE INSERT OR UPDATE ON ty_time_report_line FOR EACH ROW EXECUTE FUNCTION fn_ty_time216_report_line_guard();
CREATE TRIGGER ty_time_plan_keep BEFORE DELETE ON ty_time_plan_version FOR EACH ROW EXECUTE FUNCTION fn_ty_time216_keep();
CREATE TRIGGER ty_time_segment_keep BEFORE DELETE ON ty_time_plan_segment FOR EACH ROW EXECUTE FUNCTION fn_ty_time216_keep();
CREATE TRIGGER ty_time_report_keep BEFORE DELETE ON ty_time_report_version FOR EACH ROW EXECUTE FUNCTION fn_ty_time216_keep();
CREATE TRIGGER ty_time_report_line_keep BEFORE DELETE ON ty_time_report_line FOR EACH ROW EXECUTE FUNCTION fn_ty_time216_keep();
CREATE TRIGGER ty_time_report_adjustment_keep BEFORE UPDATE OR DELETE ON ty_time_report_adjustment FOR EACH ROW EXECUTE FUNCTION fn_ty_time216_keep();
CREATE TRIGGER ty_time_shift_keep BEFORE UPDATE OR DELETE ON ty_time_shift_version FOR EACH ROW EXECUTE FUNCTION fn_ty_time216_keep();
CREATE TRIGGER ty_time_punch_keep BEFORE UPDATE OR DELETE ON ty_time_raw_punch FOR EACH ROW EXECUTE FUNCTION fn_ty_time216_keep();
CREATE TRIGGER ty_time_plan_day_keep BEFORE DELETE ON ty_time_plan_day FOR EACH ROW EXECUTE FUNCTION fn_ty_time216_keep();
CREATE FUNCTION fn_ty_time216_punch_guard()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$
BEGIN IF NOT EXISTS(SELECT 1 FROM public.ty_employment e WHERE e.id=NEW.employment_id AND e.group_id=NEW.group_id AND e.person_id=NEW.person_id AND e.company_id=NEW.company_id AND e.status<>'cancelled'AND(NEW.punched_at AT TIME ZONE'Asia/Shanghai')::date>=e.hire_date AND(e.leave_date IS NULL OR(NEW.punched_at AT TIME ZONE'Asia/Shanghai')::date<=e.leave_date))THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='原卡须属于同集团本人有效实际关系';END IF;RETURN NEW;END;$$;
CREATE TRIGGER ty_time_raw_punch_guard BEFORE INSERT ON ty_time_raw_punch FOR EACH ROW EXECUTE FUNCTION fn_ty_time216_punch_guard();

CREATE FUNCTION fn_ty_time216_correction_source()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$
BEGIN IF NEW.source_correction_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.ty_time_punch_correction_request c JOIN public.ty_time_report_version r ON r.id=NEW.report_id WHERE c.id=NEW.source_correction_id AND c.status='approved'AND c.result_report_id=NEW.report_id AND c.person_id=NEW.person_id AND c.employment_id=NEW.employment_id AND c.group_id=r.group_id AND c.period=r.period)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='补卡派生行须引用同人的真实已核补卡及其生成报告';END IF;RETURN NULL;END;$$;
CREATE CONSTRAINT TRIGGER ty_time_correction_source_guard AFTER INSERT OR UPDATE ON ty_time_report_line DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION fn_ty_time216_correction_source();

CREATE FUNCTION fn_ty_time216_root_guard()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$
DECLARE e public.ty_employment%ROWTYPE;s public.ty_time_report_scope%ROWTYPE;r public.ty_time_report_version%ROWTYPE;
BEGIN
 SELECT*INTO e FROM public.ty_employment WHERE id=NEW.employment_id;
 IF e.id IS NULL OR e.group_id<>NEW.group_id OR e.person_id<>NEW.person_id OR(e.hire_date>=(NEW.period+interval'1 month')::date)OR(e.leave_date IS NOT NULL AND e.leave_date<NEW.period)OR(e.status='cancelled')OR NOT EXISTS(SELECT 1 FROM public.ty_company WHERE id=NEW.owner_company_id AND group_id=NEW.group_id)OR(NEW.perspective='employer'AND NEW.owner_company_id<>e.company_id)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='考勤事实根必须对应实际有效关系、月份和雇主或接收店';END IF;
 IF TG_OP='INSERT'AND(NEW.current_report_id IS NOT NULL OR NEW.head_revision<>0)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='新事实根须从未核准开始';END IF;
 IF TG_OP='UPDATE'THEN
  IF(to_jsonb(NEW)-ARRAY['current_report_id','head_revision'])IS DISTINCT FROM(to_jsonb(OLD)-ARRAY['current_report_id','head_revision'])OR NEW.head_revision<>OLD.head_revision+1 OR NEW.current_report_id IS NOT DISTINCT FROM OLD.current_report_id THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='事实根身份不可改写且采用头须连续推进';END IF;
  SELECT*INTO s FROM public.ty_time_report_scope WHERE root_id=NEW.id AND report_id=NEW.current_report_id;
  SELECT*INTO r FROM public.ty_time_report_version WHERE id=NEW.current_report_id;
  IF s.root_id IS NULL OR s.expected_head_revision<>OLD.head_revision OR s.expected_current_report_id IS DISTINCT FROM OLD.current_report_id OR r.status<>'confirmed'OR r.group_id<>NEW.group_id OR r.period<>NEW.period THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='考勤来源头已变化，不能越过草稿捕获的事实头';END IF;
 END IF;RETURN NEW;
END;$$;
CREATE TRIGGER ty_time_root_guard BEFORE INSERT OR UPDATE ON ty_time_report_root FOR EACH ROW EXECUTE FUNCTION fn_ty_time216_root_guard();
CREATE TRIGGER ty_time_root_keep BEFORE DELETE ON ty_time_report_root FOR EACH ROW EXECUTE FUNCTION fn_ty_time216_keep();
CREATE FUNCTION fn_ty_time216_scope_guard()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$
DECLARE r public.ty_time_report_version%ROWTYPE;h public.ty_time_report_root%ROWTYPE;
BEGIN
 SELECT*INTO r FROM public.ty_time_report_version WHERE id=NEW.report_id;
 SELECT*INTO h FROM public.ty_time_report_root WHERE id=NEW.root_id;
 IF r.company_id IS NOT NULL AND NOT EXISTS(WITH RECURSIVE c AS(SELECT id FROM public.ty_company WHERE id=r.company_id UNION ALL SELECT x.id FROM public.ty_company x JOIN c ON x.parent_company_id=c.id)SELECT 1 FROM c WHERE id=h.owner_company_id)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='报告范围须包含该雇主或接收店事实根';END IF;
 IF r.status<>'draft'OR r.group_id<>h.group_id OR r.period<>h.period OR NEW.expected_head_revision<>h.head_revision OR NEW.expected_current_report_id IS DISTINCT FROM h.current_report_id THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='草稿核勤范围必须捕获真实当前事实头';END IF;RETURN NEW;
END;$$;
CREATE TRIGGER ty_time_scope_guard BEFORE INSERT ON ty_time_report_scope FOR EACH ROW EXECUTE FUNCTION fn_ty_time216_scope_guard();
CREATE TRIGGER ty_time_scope_keep BEFORE UPDATE OR DELETE ON ty_time_report_scope FOR EACH ROW EXECUTE FUNCTION fn_ty_time216_keep();
CREATE FUNCTION fn_ty_time216_confirmed_roots()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$
DECLARE rid bigint;v public.ty_time_report_version%ROWTYPE;h record;expected_count integer;
BEGIN
 rid:=NEW.id;
 SELECT*INTO v FROM public.ty_time_report_version WHERE id=rid;
 IF v.status<>'confirmed'THEN RETURN NULL;END IF;
 IF NOT EXISTS(SELECT 1 FROM public.ty_time_report_scope WHERE report_id=rid)OR EXISTS(
 SELECT 1 FROM public.ty_time_report_scope s JOIN public.ty_time_report_root x ON x.id=s.root_id WHERE s.report_id=rid AND(x.current_report_id IS DISTINCT FROM rid OR x.head_revision<>s.expected_head_revision+1))THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='已核准报告必须原子推进其全部员工月份事实根';END IF;
 IF EXISTS(SELECT 1 FROM public.ty_time_report_line l WHERE l.report_id=rid AND NOT EXISTS(SELECT 1 FROM public.ty_time_report_scope s JOIN public.ty_time_report_root x ON x.id=s.root_id WHERE s.report_id=rid AND x.employment_id=l.employment_id AND x.owner_company_id=l.scope_company_id AND x.perspective=CASE WHEN l.receiving_store_only THEN'receiving'ELSE'employer'END))THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='核定行必须有对应事实根，不能脱离月度采用范围';END IF;
 FOR h IN SELECT x.*,e.hire_date,e.leave_date FROM public.ty_time_report_scope s JOIN public.ty_time_report_root x ON x.id=s.root_id JOIN public.ty_employment e ON e.id=x.employment_id WHERE s.report_id=rid LOOP
  IF v.grain='daily'THEN
   expected_count:=least(coalesce(h.leave_date,(v.period+interval'1 month' - interval'1 day')::date),(v.period+interval'1 month' - interval'1 day')::date)-greatest(h.hire_date,v.period)+1;
   IF(SELECT count(DISTINCT l.work_date)FROM public.ty_time_report_line l WHERE l.report_id=rid AND l.employment_id=h.employment_id AND l.scope_company_id=h.owner_company_id AND l.receiving_store_only=(h.perspective='receiving'))<>expected_count OR EXISTS(SELECT 1 FROM public.ty_time_report_line l WHERE l.report_id=rid AND l.employment_id=h.employment_id AND(l.work_date<h.hire_date OR l.work_date>coalesce(h.leave_date,l.work_date)))THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='日报须完整覆盖所采用员工当月有效日，未知保持NULL，不能用零掩盖缺日';END IF;
  ELSE
   IF(SELECT count(*)FROM public.ty_time_report_line l WHERE l.report_id=rid AND l.employment_id=h.employment_id AND l.scope_company_id=h.owner_company_id AND l.receiving_store_only=(h.perspective='receiving'))<>1 THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='月汇总每个事实根只能有一行，不能叠加日报';END IF;
  END IF;
 END LOOP;RETURN NULL;
END;$$;
CREATE CONSTRAINT TRIGGER ty_time_confirmed_roots AFTER UPDATE ON ty_time_report_version DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION fn_ty_time216_confirmed_roots();

CREATE FUNCTION fn_ty_time216_request_guard()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$
BEGIN
 IF TG_OP='DELETE'THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='申请与导入历史不能删除';END IF;
 IF TG_TABLE_NAME='ty_time_change_consent'THEN
  IF OLD.state<>'pending'OR NEW.state NOT IN('accepted','rejected')OR NEW.request_id<>OLD.request_id OR NEW.person_id<>OLD.person_id OR NEW.account_id IS NULL OR NEW.acted_at IS NULL THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='对方确认须从待办一次性办理，不能改写本人或既有决定';END IF;RETURN NEW;
 END IF;
 IF NEW.revision<>OLD.revision+1 THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='办理修订号须连续';END IF;
 IF TG_TABLE_NAME='ty_time_import_batch'THEN
  IF OLD.status='applied'OR(to_jsonb(NEW)-ARRAY['parsed_rows','issues','head_snapshot','status','revision','result_plan_id','result_report_id'])IS DISTINCT FROM(to_jsonb(OLD)-ARRAY['parsed_rows','issues','head_snapshot','status','revision','result_plan_id','result_report_id'])THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='已执行导入及稳定来源身份不可改写';END IF;
 ELSIF TG_TABLE_NAME='ty_time_punch_correction_request'THEN
  IF OLD.status<>'pending'OR NEW.status NOT IN('approved','rejected')OR(to_jsonb(NEW)-ARRAY['status','revision','decided_by','decision_reason','decided_at','result_report_id'])IS DISTINCT FROM(to_jsonb(OLD)-ARRAY['status','revision','decided_by','decision_reason','decided_at','result_report_id'])OR NEW.decided_by IS NULL OR NEW.decided_at IS NULL THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='补卡决定须一次性办理且不能改写原申请';END IF;
 ELSE
  IF(to_jsonb(NEW)-ARRAY['status','application_state','revision','decided_by','decision_reason','decided_at','result_plan_id'])IS DISTINCT FROM(to_jsonb(OLD)-ARRAY['status','application_state','revision','decided_by','decision_reason','decided_at','result_plan_id'])OR NOT((OLD.status='awaiting_counterparty'AND NEW.status IN('awaiting_counterparty','pending','rejected'))OR(OLD.status='pending'AND NEW.status IN('approved','rejected'))OR(OLD.status='approved'AND NEW.status='approved'AND((OLD.application_state='pending'AND NEW.application_state='applied_to_draft')OR(OLD.application_state='applied_to_draft'AND NEW.application_state='applied'))))THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='调班申请事实和决定不能退回重批';END IF;
 END IF;RETURN NEW;
END;$$;
CREATE TRIGGER ty_time_change_history BEFORE UPDATE OR DELETE ON ty_time_change_request FOR EACH ROW EXECUTE FUNCTION fn_ty_time216_request_guard();
CREATE TRIGGER ty_time_consent_history BEFORE UPDATE OR DELETE ON ty_time_change_consent FOR EACH ROW EXECUTE FUNCTION fn_ty_time216_request_guard();
CREATE TRIGGER ty_time_correction_history BEFORE UPDATE OR DELETE ON ty_time_punch_correction_request FOR EACH ROW EXECUTE FUNCTION fn_ty_time216_request_guard();
CREATE TRIGGER ty_time_import_history BEFORE UPDATE OR DELETE ON ty_time_import_batch FOR EACH ROW EXECUTE FUNCTION fn_ty_time216_request_guard();
